-- Catalog only; intended for disposable CI databases. No customer rows are read.
SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'acl',c.relacl,'column_acl',(SELECT jsonb_agg(a.attacl) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attacl IS NOT NULL),'effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,c.oid,'TRIGGER'),'maintain',has_table_privilege(r.oid,c.oid,'MAINTAIN'),'any_column_select',has_any_column_privilege(r.oid,c.oid,'SELECT'),'any_column_insert',has_any_column_privilege(r.oid,c.oid,'INSERT'),'any_column_update',has_any_column_privilege(r.oid,c.oid,'UPDATE'),'any_column_references',has_any_column_privilege(r.oid,c.oid,'REFERENCES'))) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated')))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%'),
 'policies',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p)
) AS audit;
